"""A deterministic, local product prototype using the film's exact source data."""
from pathlib import Path
import json
P=Path(__file__).resolve().parent;data=json.loads((P.parent/'data/validated.json').read_text())
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TRACE · 产品原型</title><style>
*{box-sizing:border-box}body{margin:0;background:#eceef6;color:#272b38;font:16px -apple-system,BlinkMacSystemFont,"Helvetica Neue",sans-serif}button,textarea{font:inherit}button{cursor:pointer}main{margin:5vh auto;width:min(1450px,96vw);min-height:86vh;display:grid;grid-template-columns:208px 1fr;background:white;border:1px solid #dedfea;border-radius:20px;box-shadow:0 30px 80px #45496320;overflow:hidden}aside{background:#f2f1f7;padding:30px 24px}h1{font-size:28px;letter-spacing:-1px;margin:0 0 12px}.muted{color:#7a8092}nav{margin:35px 0}nav button{display:block;width:100%;border:0;background:transparent;text-align:left;padding:14px;border-radius:9px;color:#7a8092;margin-bottom:8px}nav button.active{background:#ecebfc;color:#5655e9}.files{border-top:1px solid #dedfea;padding-top:24px;font-size:14px;line-height:3}section header{border-bottom:1px solid #dedfea;padding:24px 34px;display:flex;justify-content:space-between}.ready{font-size:13px;color:#699786}.body{padding:36px}h2{font-size:34px;font-weight:600;margin:36px 0 28px}textarea{width:100%;height:160px;padding:24px 85px 24px 24px;resize:vertical;line-height:1.7;font-size:23px;background:#fafafd;color:#272b38;border:1px solid #dedfea;border-radius:16px}form{position:relative}form button{position:absolute;right:20px;bottom:24px;border:0;border-radius:50%;background:#5655e9;color:white;width:48px;height:48px;font-size:26px}.attachments{display:flex;gap:16px;margin:26px 0}.file{background:#f7f7fb;padding:20px;flex:1;border-radius:12px}.file span{display:block;color:#5655e9;font:13px monospace;margin-bottom:12px}.answer{margin-top:30px;display:grid;grid-template-columns:minmax(280px,1fr) minmax(250px,.7fr);gap:32px}.answer h3{font-size:24px}.chips span{display:inline-block;background:#f1f3f9;color:#5655e9;border-radius:8px;padding:8px 16px;margin-right:8px}.quote{background:#ecebfc;border:0;border-radius:8px;padding:20px;text-align:left;width:100%;font-size:17px;line-height:1.7;color:#272b38;display:flex;justify-content:space-between;gap:20px}.quote b{color:#5655e9;flex-shrink:0}.source{background:#f8f8fc;padding:26px;border-radius:16px}.source h3{font-size:28px}.source blockquote{margin:24px 0;background:#ecebfc;padding:20px;line-height:1.8}.source small{color:#5655e9}.footer{font-size:12px;color:#7a8092;max-width:1450px;margin:0 auto 30px;padding:0 24px}.answer[hidden]{display:none}#notice{color:#5655e9;margin:18px 0}.download{color:#5655e9;text-decoration:none;display:inline-block;margin-top:22px}@media(max-width:850px){main{grid-template-columns:1fr}aside{display:none}.body{padding:24px}.attachments{flex-direction:column}.answer{grid-template-columns:1fr}}
</style><main><aside><h1>TRACE</h1><span class="muted">产品团队</span><nav><button class="active" type="button">知识库</button><button id="reset" type="button">新建对话</button></nav><div class="files">资料库<div>▤ 发布说明</div><div>▤ 同步与更新</div><div>▤ 访问与权限</div></div></aside><section><header><span>知识库 / 新对话</span><span class="ready">● 资料已同步</span></header><div class="body"><h2>你想了解什么？</h2><form id="query"><textarea id="question" aria-label="向知识库提问">知识库支持哪些文件？更新后，怎样生效？</textarea><button aria-label="发送问题">↑</button></form><div class="attachments" id="attachments"></div><div id="notice" role="status"></div><div class="answer" id="answer" hidden><div id="answer-content"></div><div id="source" class="source"></div></div></div></section></main><p class="footer">原创软件交互原型。资料为虚构产品示例，采用本地关键词匹配与原文引用，未接入在线大模型。宣传片中的源文、编号与本原型一致。</p><script>const DATA=__DATA__;
function el(tag,text){const x=document.createElement(tag);x.textContent=text;return x;}
for(const d of DATA.documents){const x=el('div','');x.className='file';x.append(el('span',d.format),el('strong',d.title));document.querySelector('#attachments').append(x);}
function retrieve(q){const ids=[];if(/文件|格式|支持|PDF|Markdown|TXT/i.test(q))ids.push('release');if(/更新|同步|修改|生效/.test(q))ids.push('sync');if(/权限|访问|授权/.test(q))ids.push('access');return DATA.documents.filter(d=>ids.includes(d.id));}
function showSource(d){const p=document.querySelector('#source');p.replaceChildren(el('small','来源 '+d.number+' / '+d.format),el('h3',d.title),el('p',d.section+' / 版本 '+d.version));const q=el('blockquote',d.excerpt.join(' '));p.append(q,el('p',d.context.join(' ')));}
document.querySelector('#query').addEventListener('submit',e=>{e.preventDefault();const docs=retrieve(document.querySelector('#question').value),answer=document.querySelector('#answer'),body=document.querySelector('#answer-content');body.replaceChildren();document.querySelector('#notice').textContent=docs.length?'已定位 '+docs.length+' 份相关资料':'这组示例资料暂不包含相关内容，请尝试文件格式、同步或权限问题。';answer.hidden=!docs.length;if(!docs.length)return;body.append(el('h3','根据产品资料'),el('p','以下内容来自你的知识库。'));for(const d of docs){body.append(el('h4',d.section));if(d.id==='release'){const chips=el('div','');chips.className='chips';for(const s of ['PDF','Markdown','TXT'])chips.append(el('span',s));body.append(chips);}const b=el('button','');b.className='quote';b.append(el('span',d.excerpt.join(' ')),el('b',d.number));b.onclick=()=>showSource(d);body.append(b);}showSource(docs[0]);const payload={question:document.querySelector('#question').value,answers:docs.map(d=>({source:d.title,section:d.section,quote:d.excerpt}))};const link=el('a','下载带来源的答案 JSON');link.className='download';link.download='TRACE-answer.json';link.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));body.append(link);});
document.querySelector('#reset').onclick=()=>{document.querySelector('#answer').hidden=true;document.querySelector('#notice').textContent='';document.querySelector('#question').focus();};
</script></html>'''
(P/'TRACE产品原型.html').write_text(html.replace('__DATA__',json.dumps(data,ensure_ascii=False)),encoding='utf-8')
(P/'TRACE示例资料.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
print(P/'TRACE产品原型.html')
